{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "Outdated AMI used",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "The AMI being used is Ubuntu 14.04, which is an outdated and unsupported version. This poses a security risk as it no longer receives security updates or patches."
    },
    {
      "check_id": "CKV_AWS_23",
      "title": "Public IP address assigned to an instance",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "One of the instances is configured to have a public IP address. This increases the attack surface and could expose the instance to unauthorized access if not properly secured."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_latest.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id = aws_subnet.my_subnet.id\n}",
  "fix_summary": "Updated the AMI to use the latest Ubuntu version and disabled public IP assignment for all instances."
}
